import{_ as s,o as a,c as t,a2 as n}from"./chunks/framework.7w-lhQN6.js";const u=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1793550481000}'),i={name:"faq.md"};function o(h,e,l,d,r,c){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p>This page answers the questions that come up most once you are past setup: what happens when the CLI and the extension collide, why a report might look thinner than you expect, and what the dashboard&#39;s status is.</p><h2 id="can-i-run-mcp-lens-scan-while-the-vs-code-extension-is-open" tabindex="-1">Can I run <code>mcp-lens scan</code> while the VS Code extension is open? <a class="header-anchor" href="#can-i-run-mcp-lens-scan-while-the-vs-code-extension-is-open" aria-label="Permalink to &quot;Can I run `mcp-lens scan` while the VS Code extension is open?&quot;">​</a></h2><p>Yes, but only one of them writes at a time. Both the extension and the CLI&#39;s <code>scan</code> and <code>auth</code> commands contend for the same writer lease before they save to <code>~/.mcplens/lens.db</code>. If the extension already holds it, the CLI command refuses to run and prints:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>The VS Code extension is writing the MCP Lens DB, so this command cannot run right now.</span></span>\n<span class="line"><span>Close the extension window (or the other running mcp-lens) and try again. It may also clear on its own shortly.</span></span></code></pre></div><p><code>mcp-lens report</code> never needs to refuse: it saves its log backfill when it can take the lease, and simply skips that save and runs read-only when it cannot, printing the same report either way. Still, treat the refusal as a safety net rather than a workflow: avoid running the CLI and the extension against the database at the same time.</p><h2 id="why-does-my-report-only-cover-the-last-30-days-by-default" tabindex="-1">Why does my report only cover the last 30 days by default? <a class="header-anchor" href="#why-does-my-report-only-cover-the-last-30-days-by-default" aria-label="Permalink to &quot;Why does my report only cover the last 30 days by default?&quot;">​</a></h2><p><code>--days</code> defaults to 30, matching how long the original client logs (Claude Code, Codex, Gemini CLI) keep their session history before they expire on their own. The Lens database keeps every observation it has already ingested permanently, so once you have been running Lens for longer than 30 days you can pass a larger <code>--days</code> value and see further back. What you cannot do is backfill the period before you installed Lens, because the source logs for that period are already gone.</p><h2 id="which-clients-support-global-actions" tabindex="-1">Which clients support global actions? <a class="header-anchor" href="#which-clients-support-global-actions" aria-label="Permalink to &quot;Which clients support global actions?&quot;">​</a></h2><p>Only Claude Code and Codex. Global actions disable an unused MCP tool by editing that client&#39;s own config file, and Gemini CLI is not a target for that edit. Gemini CLI still gets full scanning, hook collection, and reporting, it just never has a tool turned off for it automatically. See <a href="/MCPLens/guide/global-actions">Global Actions</a> for how the rollout setting controls this per client.</p><h2 id="is-the-local-dashboard-still-maintained" tabindex="-1">Is the local dashboard still maintained? <a class="header-anchor" href="#is-the-local-dashboard-still-maintained" aria-label="Permalink to &quot;Is the local dashboard still maintained?&quot;">​</a></h2><p>No, it is frozen. Its code and tests still work as of the freeze, and you can still run it with <code>npm start -w @mcp-lens/dashboard</code>, but no new features land there because the VS Code sidebar absorbed that role. Use the extension&#39;s sidebar for anything beyond a quick look; see <a href="/MCPLens/guide/dashboard">Dashboard</a> for what still works.</p><h2 id="i-installed-hooks-but-my-usage-is-always-zero-what-s-wrong" tabindex="-1">I installed hooks but my usage is always zero. What&#39;s wrong? <a class="header-anchor" href="#i-installed-hooks-but-my-usage-is-always-zero-what-s-wrong" aria-label="Permalink to &quot;I installed hooks but my usage is always zero. What&#39;s wrong?&quot;">​</a></h2><p>If you are on the CLI-only path, this is a current limitation rather than a misconfiguration. The hooks write each call into the <code>~/.mcplens/inbox</code> queue, and the VS Code extension is the only component that drains that queue into <code>~/.mcplens/lens.db</code>. The <code>mcp-lens</code> CLI has no drain path at all, so with the extension never running those records stay queued and never reach the database.</p><p>Check it with <code>mcp-lens hooks status</code>. If the <code>pending</code> count keeps growing instead of returning to 0, that is exactly this situation, and <code>mcp-lens hooks doctor</code> raises a warning for the same events:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcp-lens</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hooks</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>The <code>pending</code> line is the one to watch (field names below are real, the number is illustrative):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  pending: 128</span></span></code></pre></div><p>Nothing is lost while they wait. Run the <a href="/MCPLens/guide/vscode-extension">VS Code extension</a> once and it drains the whole queue. Until then, the only usage <code>mcp-lens report</code> can show is what it recovers by parsing each client&#39;s own session logs, which is a separate path from the inbox. See <a href="/MCPLens/concepts/how-it-works">How It Works</a> for both paths in full.</p><p>If you are already running the extension and the <code>calls</code> column is still zero, the cause is per-client. Codex in particular needs its hook hash trusted; see the next question.</p><h2 id="my-codex-hooks-are-installed-but-no-events-show-up-what-s-wrong" tabindex="-1">My Codex hooks are installed but no events show up. What&#39;s wrong? <a class="header-anchor" href="#my-codex-hooks-are-installed-but-no-events-show-up-what-s-wrong" aria-label="Permalink to &quot;My Codex hooks are installed but no events show up. What&#39;s wrong?&quot;">​</a></h2><p>Codex skips plugin-bundled hooks, including MCP Lens&#39;s, until you trust their current hook-definition hash. Run <code>mcp-lens hooks doctor codex</code> to check:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcp-lens</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hooks</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codex</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[WARNING] codex codex-trust-unapproved: Codex hook trust is not approved; review it with /hooks.</span></span></code></pre></div><p>If you see that warning, open <code>/hooks</code> inside a Codex session, review the MCP Lens hook definition, and trust its current hash. Start a new Codex session afterward, since the hook state only takes effect on the next session. Review the hash again whenever the plugin updates and the hash changes.</p><h2 id="why-did-npx-mcp-lens-run-something-i-didn-t-expect" tabindex="-1">Why did <code>npx mcp-lens</code> run something I didn&#39;t expect? <a class="header-anchor" href="#why-did-npx-mcp-lens-run-something-i-didn-t-expect" aria-label="Permalink to &quot;Why did `npx mcp-lens` run something I didn&#39;t expect?&quot;">​</a></h2><p>An unrelated package is already published to npm under the name <code>mcp-lens</code>. Plain <code>npx mcp-lens</code> downloads and runs that third-party package whenever there is no local bin available, which is not this project. MCP Lens itself is not published to npm; you build it from the repository and use the workspace bin. Always use <code>npx --no-install mcp-lens</code> so npx only runs a bin that is already installed locally, or call the linked bin directly:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> link</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -w</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @mcp-lens/cli</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcp-lens</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div>',28)])])}const k=s(i,[["render",o]]);export{u as __pageData,k as default};
